import math


def _bars_per_year(ctx):
    """Sampling rate of the feed, from the timestamps' dates alone.

    A count of bars per calendar date, medianed. This is the clock, not the
    prices -- the timeframe of a backtest is a priori knowledge.
    """
    cnt = {}
    for b in ctx.bars:
        d = b["t"][0:10]
        cnt[d] = cnt.get(d, 0) + 1
    vals = sorted(cnt.values())
    if not vals:
        return 252.0
    per_day = vals[len(vals) // 2]
    return 252.0 * max(1, per_day)


def family_init(ctx):
    b = ctx.bars
    n = len(b)
    cl = [float(x["c"]) for x in b]
    bpy = _bars_per_year(ctx)
    lb = max(20, int(ctx.p.lb))
    hold = max(2, int(ctx.p.hold))
    com = max(10, int(lb * float(ctx.p.com_frac)))
    a = 1.0 / (com + 1.0)
    vt = float(ctx.p.vol_target)
    cap = float(ctx.p.lev_cap)
    mlev = float(ctx.p.min_lev)

    ew = None
    sig = [0] * n
    sga = [None] * n
    state = 0
    for t in range(n):
        if t >= 1 and cl[t] > 0.0 and cl[t - 1] > 0.0:
            r = math.log(cl[t] / cl[t - 1])
            ew = r * r if ew is None else ew + a * (r * r - ew)
        if ew is not None and ew > 0.0:
            sga[t] = math.sqrt(bpy * ew)
        if t >= lb and t % hold == 0 and sga[t] is not None and cl[t - lb] > 0.0:
            lev = vt / sga[t] if sga[t] > 0.0 else 0.0
            if lev > cap:
                lev = cap
            if lev < mlev:
                state = 0
            else:
                rl = cl[t] / cl[t - lb] - 1.0
                state = 1 if rl > 0.0 else (-1 if rl < 0.0 else 0)
        sig[t] = state
    ctx.f_sig = sig
    ctx.f_sga = sga
    ctx._hw = None
    ctx._hwe = None


def signal(ctx, i):
    return ctx.f_sig[i]


def exit_signal(ctx, i):
    if not ctx.positions or not int(ctx.p.dd_on):
        return False
    e = min(p["entry_i"] for p in ctx.positions)
    c = ctx.c[i]
    if c is None or c <= 0.0:
        return False
    if ctx._hwe != e:
        ctx._hwe = e
        ctx._hw = c
    d = 1 if ctx.positions[0]["side"] == "long" else -1
    if d > 0:
        if c > ctx._hw:
            ctx._hw = c
        dd = (ctx._hw - c) / ctx._hw if ctx._hw > 0.0 else 0.0
    else:
        if c < ctx._hw:
            ctx._hw = c
        dd = (c - ctx._hw) / ctx._hw if ctx._hw > 0.0 else 0.0
    s = ctx.f_sga[i]
    if s is None or s <= 0.0:
        return False
    return dd > float(ctx.p.dd_mult) * s / math.sqrt(12.0)
